const out = [];
for (const it of $input.all()) {
  const j = it.json;
  const body = j.body && j.body.events ? j.body : j;
  for (const ev of (body.events || [])) out.push({ json: { event: ev } });
}
return out;

// F3 回診：新增 / 編輯 / 取消 —— 依 Line 事件決定要寫入的資料與回覆訊息
// 輸出兩種 item：{kind:'write', row:{...}} 與 {kind:'reply', replyToken, messages}
const clean = (name) => $(name).all().map(i => i.json).filter(r => r && Object.keys(r).length > 0);
const users = clean('讀取 users');
const links = clean('讀取 family_links');
const patients = clean('讀取 patients');
const appts = clean('讀取 appointments');

const TZ = 'Asia/Taipei';
const now = DateTime.now().setZone(TZ);
const today = now.toISODate();
const SESSIONS = ['早診', '午診', '晚診'];
const WEEK = ['一', '二', '三', '四', '五', '六', '日'];
const ACTIVE = ['scheduled', 'edit_hospital'];
const BLUE = '#1E6FD9';
const OTHER_KEYWORDS = ['問醫師', '記血壓', '記血糖', '吃藥了', '拍報告', '出示摘要', '更多'];

function parseQS(str) {
  const m = {};
  for (const part of String(str || '').split('&')) {
    if (!part) continue;
    const i = part.indexOf('=');
    const k = decodeURIComponent(i < 0 ? part : part.slice(0, i));
    m[k] = decodeURIComponent((i < 0 ? '' : part.slice(i + 1)).replace(/\+/g, ' '));
  }
  return { get: (k) => (k in m ? m[k] : null) };
}
const s = (v) => (v === undefined || v === null ? '' : String(v).trim());
function normDate(v) {
  if (typeof v === 'number') return DateTime.fromISO('1899-12-30', { zone: TZ }).plus({ days: v }).toISODate();
  const t = s(v).replace(/\//g, '-');
  const dt = DateTime.fromISO(t, { zone: TZ });
  return dt.isValid ? dt.toISODate() : t;
}
const row = (a) => ({
  appt_id: s(a.appt_id), patient_id: s(a.patient_id), date: normDate(a.date),
  session: s(a.session), hospital: s(a.hospital), department: s(a.department), status: s(a.status),
});
const newId = () => 'APT' + now.toFormat('yyMMddHHmmss') + Math.floor(Math.random() * 900 + 100);
function fmtDate(d) {
  const dt = DateTime.fromISO(d, { zone: TZ });
  return dt.isValid ? `${dt.toFormat('M/d')}（${WEEK[dt.weekday - 1]}）` : d;
}
const daysUntil = (d) => Math.round(DateTime.fromISO(d, { zone: TZ }).startOf('day').diff(now.startOf('day'), 'days').days);
const place = (a) => `${a.hospital} ${a.department}`.trim();

function reminderText(a) {
  const d = daysUntil(a.date);
  const left = [7, 3, 1].filter((n) => n < d || (n === d && now.hour < 9));
  if (left.length === 0) return d >= 0 ? '事前提醒時間已過，回診當晚會提醒記醫囑' : '這筆回診日期已過';
  return `將在回診前 ${left.join('、')} 天早上 9 點用 Line 提醒`;
}

// ---------- 訊息 ----------
const textMsg = (text, quickItems) => {
  const m = { type: 'text', text };
  if (quickItems && quickItems.length) m.quickReply = { items: quickItems.map((action) => ({ type: 'action', action })) };
  return m;
};
const pb = (label, data, displayText) => ({ type: 'postback', label, data, displayText: displayText || label });
const datePicker = (label, id, initial) => ({
  type: 'datetimepicker', label, data: `action=appt_date&id=${id}`, mode: 'date',
  initial: initial && initial >= today ? initial : today, min: today,
});

function askDate(id, initial) {
  return {
    type: 'flex', altText: '請選擇回診日期',
    contents: {
      type: 'bubble',
      body: { type: 'box', layout: 'vertical', spacing: 'md', contents: [
        { type: 'text', text: '請選擇回診日期', size: 'xl', weight: 'bold', color: '#222222' },
        { type: 'text', text: '點下方按鈕，從日曆選日期', size: 'md', color: '#555555', wrap: true },
      ] },
      footer: { type: 'box', layout: 'vertical', contents: [
        { type: 'button', style: 'primary', color: BLUE, height: 'md', action: datePicker('選擇日期', id, initial) },
      ] },
    },
  };
}
const isTime = (v) => /^([01]\d|2[0-3]):[0-5]\d$/.test(s(v));
const timePicker = (label, a) => ({
  type: 'datetimepicker', label, data: `action=appt_time&id=${a.appt_id}`, mode: 'time',
  initial: isTime(a.session) ? a.session : '09:00',
});
const askSession = (a, note) => ({
  type: 'flex', altText: '請選擇看診時間',
  contents: {
    type: 'bubble',
    body: { type: 'box', layout: 'vertical', spacing: 'md', contents: [
      { type: 'text', text: `回診日期：${fmtDate(a.date)}`, size: 'md', color: '#555555' },
      { type: 'text', text: note || '請選擇看診時間', size: 'xl', weight: 'bold', color: '#222222', wrap: true },
    ] },
    footer: { type: 'box', layout: 'vertical', contents: [
      { type: 'button', style: 'primary', color: BLUE, height: 'md', action: timePicker('選擇時間', a) },
    ] },
  },
});
const askHospital = (extra) => textMsg(`${extra ? extra + '\n' : ''}請輸入「醫院 科別」，中間空一格\n例如：台大 新陳代謝科\n（輸入「取消」可離開）`);

function card(a, title) {
  return {
    type: 'bubble',
    header: { type: 'box', layout: 'vertical', backgroundColor: BLUE, paddingAll: '16px', contents: [
      { type: 'text', text: title, color: '#FFFFFF', size: 'lg', weight: 'bold' },
    ] },
    body: { type: 'box', layout: 'vertical', spacing: 'md', contents: [
      { type: 'text', text: fmtDate(a.date), size: 'xxl', weight: 'bold', color: '#222222' },
      { type: 'text', text: a.session ? `時間 ${a.session}` : '（尚未選時間）', size: 'lg', color: '#222222' },
      { type: 'text', text: place(a) || '（尚未填醫院科別）', size: 'lg', color: '#222222', wrap: true },
      { type: 'separator', margin: 'md' },
      { type: 'text', text: reminderText(a), size: 'md', color: '#555555', wrap: true, margin: 'md' },
    ] },
    footer: { type: 'box', layout: 'horizontal', spacing: 'md', contents: [
      { type: 'button', style: 'secondary', height: 'md', action: pb('修改', `action=appt_edit&id=${a.appt_id}`, '修改回診') },
      { type: 'button', style: 'secondary', height: 'md', action: pb('取消回診', `action=appt_cancel&id=${a.appt_id}`) },
    ] },
  };
}
const cardMsg = (a, title) => ({ type: 'flex', altText: `${title}：${fmtDate(a.date)} ${a.session} ${place(a)}`, contents: card(a, title) });

function editMenu(a) {
  return textMsg(`要修改哪一項？\n目前：${fmtDate(a.date)} ${a.session} ${place(a)}`, [
    datePicker('改日期', a.appt_id, a.date),
    timePicker('改時間', a),
    pb('改醫院科別', `action=appt_edit_hosp&id=${a.appt_id}`),
    pb('取消回診', `action=appt_cancel&id=${a.appt_id}`),
  ]);
}
const newBtn = pb('新增回診', 'action=appt_new');
function menuCard() {
  return {
    type: 'flex', altText: '回診：新增回診／我的回診',
    contents: {
      type: 'bubble',
      body: { type: 'box', layout: 'vertical', spacing: 'md', contents: [
        { type: 'text', text: '回診', size: 'xl', weight: 'bold', color: '#222222' },
        { type: 'text', text: '要做什麼？', size: 'md', color: '#555555' },
      ] },
      footer: { type: 'box', layout: 'vertical', spacing: 'md', contents: [
        { type: 'button', style: 'primary', color: BLUE, height: 'md', action: pb('新增回診', 'action=appt_new') },
        { type: 'button', style: 'secondary', height: 'md', action: pb('我的回診', 'action=appt_list') },
      ] },
    },
  };
}

// ---------- 身分 ----------
function resolve(lineUserId) {
  const u = users.find((r) => s(r.line_user_id) === lineUserId);
  if (!u) return null;
  if (s(u.role) === 'patient') {
    const p = patients.find((r) => s(r.user_id) === s(u.user_id));
    return p ? s(p.patient_id) : null;
  }
  const l = links.find((r) => s(r.family_user_id) === s(u.user_id) && s(r.status) === 'active');
  return l ? s(l.patient_id) : null;
}

// ---------- 主流程 ----------
const out = [];
let curReplyToken = null; // 目前處理中事件的 replyToken，讓 write item 也帶著，存檔失敗時才能回覆使用者
const write = (r) => {
  out.push({ json: { kind: 'write', row: r, replyToken: curReplyToken } });
  const i = appts.findIndex((x) => s(x.appt_id) === r.appt_id);
  if (i >= 0) appts[i] = r; else appts.push(r);
};

for (const item of $('解析事件').all()) {
  const ev = item.json.event || {};
  if (!ev.replyToken || !ev.source || !ev.source.userId) continue;
  curReplyToken = ev.replyToken;
  const msgs = [];
  const reply = (...m) => msgs.push(...m);

  let action = null, q = parseQS(''), text = null;
  if (ev.type === 'postback' && ev.postback) {
    q = parseQS(ev.postback.data);
    action = q.get('action') || '';
    if (!action.startsWith('appt_')) continue; // 不是回診功能的按鈕，交給其他流程
  } else if (ev.type === 'message' && ev.message && ev.message.type === 'text') {
    text = s(ev.message.text);
    if (text === '回診') action = 'appt_menu';
    else if (text === '新增回診') action = 'appt_new';
    else if (text === '我的回診' || text === '查看回診') action = 'appt_list';
  } else continue;

  const pid = resolve(ev.source.userId);
  if (!pid) {
    if (action) reply(textMsg('還找不到你的帳號資料。請先完成加入與同意，家人請先用邀請碼綁定，再使用回診功能。'));
    if (msgs.length) out.push({ json: { kind: 'reply', replyToken: ev.replyToken, messages: msgs } });
    continue;
  }
  const mine = () => appts.map(row).filter((a) => a.patient_id === pid);
  const findMine = (id) => mine().find((a) => a.appt_id === id);
  const id = q.get('id') || '';

  // 一般文字：只有在「等待輸入醫院科別」時才處理
  if (!action && text !== null) {
    const pending = mine().find((a) => a.status === 'edit_hospital') ||
      mine().find((a) => a.status === 'draft' && a.date && a.session);
    const draftNoSession = mine().find((a) => a.status === 'draft' && a.date && !a.session);
    const tokens = text.split(/\s+/).filter(Boolean);
    const looksOther = tokens.some((t) => /^[\d\/.,:-]+$/.test(t)) || OTHER_KEYWORDS.some((k) => text.startsWith(k));
    if (!pending && !draftNoSession) continue;
    if (looksOther) continue; // 可能是血壓、血糖等，交給 F1
    if (text === '取消') {
      const p = pending || draftNoSession;
      write({ ...p, status: p.status === 'edit_hospital' ? 'scheduled' : 'cancelled' });
      reply(textMsg(p.status === 'edit_hospital' ? '好的，醫院科別維持不變。' : '好的，已取消新增回診。', [newBtn]));
    } else if (!pending) {
      reply(askSession(draftNoSession, '請先選擇看診時間'));
    } else if (tokens.length < 2) {
      reply(askHospital('醫院和科別中間要空一格喔'));
    } else {
      const updated = { ...pending, hospital: tokens[0].slice(0, 30), department: tokens.slice(1).join(' ').slice(0, 30), status: 'scheduled' };
      const isNew = pending.status === 'draft';
      write(updated);
      reply(cardMsg(updated, isNew ? '回診已建立' : '回診已更新'));
    }
  } else if (action === 'appt_menu') {
    reply(menuCard());
  } else if (action === 'appt_new') {
    const draft = mine().find((a) => a.status === 'draft');
    reply(askDate(draft ? draft.appt_id : 'new'));
  } else if (action === 'appt_list') {
    const list = mine().filter((a) => ACTIVE.includes(a.status) && a.date >= today)
      .sort((x, y) => (x.date + x.session).localeCompare(y.date + y.session)).slice(0, 10);
    if (!list.length) reply(textMsg('目前沒有安排中的回診。', [newBtn]));
    else reply({ type: 'flex', altText: `你有 ${list.length} 筆回診`, contents: { type: 'carousel', contents: list.map((a) => card(a, '即將回診')) } });
  } else if (action === 'appt_date') {
    const date = normDate(ev.postback.params && ev.postback.params.date);
    if (!date || date < today) {
      reply(textMsg('回診日期不能早於今天，請重新選擇。'), askDate(id));
    } else if (id === 'new' || (findMine(id) && findMine(id).status === 'draft')) {
      const base = id === 'new' ? null : findMine(id);
      const d = { appt_id: base ? base.appt_id : newId(), patient_id: pid, date, session: '', hospital: '', department: '', status: 'draft' };
      write(d);
      reply(askSession(d));
    } else {
      const a = findMine(id);
      if (!a || !ACTIVE.includes(a.status)) reply(textMsg('這筆回診已取消或已改期，請輸入「我的回診」查看最新資料。'));
      else if (a.date === date) reply(cardMsg(a, '回診日期沒有變更'));
      else {
        // 改期 = 取消舊的、建立新的（提醒紀錄以 appt_id 區分，才不會漏發）
        write({ ...a, status: 'cancelled' });
        const n = { ...a, appt_id: newId(), date, status: 'scheduled' };
        write(n);
        reply(cardMsg(n, '回診已改期'));
      }
    }
  } else {
    const a = findMine(id);
    if (!a) { reply(textMsg('找不到這筆回診，請輸入「我的回診」查看。')); }
    else if (a.status === 'cancelled') { reply(textMsg('這筆回診已取消或已改期，請輸入「我的回診」查看最新資料。')); }
    else if (a.status !== 'draft' && a.date < today) { reply(textMsg('這筆回診日期已經過了，無法修改。', [newBtn])); }
    else if (action === 'appt_session' || action === 'appt_time') {
      const v = action === 'appt_time' ? s(ev.postback.params && ev.postback.params.time) : q.get('v');
      if (action === 'appt_time' ? !isTime(v) : !SESSIONS.includes(v)) reply(askSession(a));
      else if (action === 'appt_time' && a.date === today && v <= now.toFormat('HH:mm')) reply(askSession(a, '這個時間已經過了，請重新選擇'));
      else if (a.status === 'draft') { write({ ...a, session: v }); reply(askHospital(`時間：${v}`)); }
      else { const u = { ...a, session: v, status: 'scheduled' }; write(u); reply(cardMsg(u, '回診已更新')); }
    } else if (a.status === 'draft') {
      reply(textMsg('這筆回診還沒建立完成，請繼續上一步。'));
    } else if (action === 'appt_edit') reply(editMenu(a));
    else if (action === 'appt_pick_session') reply(askSession(a));
    else if (action === 'appt_edit_hosp') { write({ ...a, status: 'edit_hospital' }); reply(askHospital(`目前：${place(a)}`)); }
    else if (action === 'appt_cancel') {
      reply(textMsg(`確定要取消 ${fmtDate(a.date)} ${a.session} ${place(a)} 的回診嗎？取消後就不會再提醒。`, [
        pb('確定取消', `action=appt_cancel_ok&id=${a.appt_id}`), pb('保留', `action=appt_keep&id=${a.appt_id}`),
      ]));
    } else if (action === 'appt_cancel_ok') {
      write({ ...a, status: 'cancelled' });
      reply(textMsg(`已取消 ${fmtDate(a.date)} 的回診，不會再提醒。`, [newBtn]));
    } else if (action === 'appt_keep') reply(cardMsg(a, '回診已保留'));
    else continue;
  }
  if (msgs.length) out.push({ json: { kind: 'reply', replyToken: ev.replyToken, messages: msgs.slice(0, 5) } });
}
return out;

// F3 回診提醒：找出今天該發的提醒（09:00 → 前 7/3/1 天；20:00 → 回診當天晚上記醫囑）
const cfg = $('提醒設定').first().json;
const clean = (name) => $(name).all().map(i => i.json).filter(r => r && Object.keys(r).length > 0);
const appts = clean('提醒｜讀取 appointments');
const users = clean('提醒｜讀取 users');
const patients = clean('提醒｜讀取 patients');
const links = clean('提醒｜讀取 family_links');
const logs = clean('提醒｜讀取 notification_log');

const TZ = 'Asia/Taipei';
const WEEK = ['一', '二', '三', '四', '五', '六', '日'];
const BLUE = '#1E6FD9';
const s = (v) => (v === undefined || v === null ? '' : String(v).trim());
function normDate(v) {
  if (typeof v === 'number') return DateTime.fromISO('1899-12-30', { zone: TZ }).plus({ days: v }).toISODate();
  const dt = DateTime.fromISO(s(v).replace(/\//g, '-'), { zone: TZ });
  return dt.isValid ? dt.toISODate() : s(v);
}
const today = s(cfg.TEST_TODAY)
  ? DateTime.fromISO(s(cfg.TEST_TODAY), { zone: TZ }).startOf('day')
  : DateTime.now().setZone(TZ).startOf('day');
const mode = s(cfg.MODE) || 'morning';
const offsets = mode === 'evening' ? [0] : [7, 3, 1];

const uuid = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
  const r = Math.random() * 16 | 0; return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
});
const userById = (uid) => users.find((u) => s(u.user_id) === s(uid));
const alreadySent = (apptId, userId, offset) => logs.some((l) =>
  s(l.appt_id) === apptId && s(l.user_id) === userId && s(l.channel) === 'line' &&
  Number(l.offset_days) === offset && s(l.status) === 'sent');

function fmtDate(d) {
  const dt = DateTime.fromISO(d, { zone: TZ });
  return `${dt.toFormat('M/d')}（${WEEK[dt.weekday - 1]}）`;
}

function reminder(a, offset, patientName, isFamily) {
  const who = isFamily && patientName ? `${patientName}` : '你';
  const place = `${a.hospital} ${a.department}`.trim();
  if (offset === 0) {
    return [{ type: 'text', text: `${isFamily ? patientName + '今天' : '今天'}看診辛苦了！\n醫師交代了什麼？\n點「更多 → 記醫囑」記下來，下次回診摘要會幫忙整理。` }];
  }
  const title = offset === 1 ? '明天要回診' : `${offset} 天後要回診`;
  const bubble = {
    type: 'bubble',
    header: { type: 'box', layout: 'vertical', backgroundColor: BLUE, paddingAll: '16px', contents: [
      { type: 'text', text: `回診提醒：${title}`, color: '#FFFFFF', size: 'lg', weight: 'bold', wrap: true },
    ] },
    body: { type: 'box', layout: 'vertical', spacing: 'md', contents: [
      ...(isFamily ? [{ type: 'text', text: `${who}的回診`, size: 'md', color: '#555555' }] : []),
      { type: 'text', text: fmtDate(a.date), size: 'xxl', weight: 'bold', color: '#222222' },
      { type: 'text', text: /^\d{2}:\d{2}$/.test(a.session) ? `時間 ${a.session}` : (a.session || '—'), size: 'lg', color: '#222222' },
      { type: 'text', text: place, size: 'lg', color: '#222222', wrap: true },
      ...(offset === 1 ? [{ type: 'text', text: '記得帶健保卡', size: 'md', color: '#555555', margin: 'md' }] : []),
    ] },
  };
  if (offset === 1 && s(cfg.LIFF_SUMMARY_URL)) {
    bubble.footer = { type: 'box', layout: 'vertical', contents: [
      { type: 'button', style: 'primary', color: BLUE, height: 'md', action: { type: 'uri', label: '出示摘要', uri: s(cfg.LIFF_SUMMARY_URL) } },
    ] };
  }
  return [{ type: 'flex', altText: `回診提醒：${title}，${fmtDate(a.date)} ${a.session} ${place}`, contents: bubble }];
}

const out = [];
for (const raw of appts) {
  const a = { appt_id: s(raw.appt_id), patient_id: s(raw.patient_id), date: normDate(raw.date),
    session: s(raw.session), hospital: s(raw.hospital), department: s(raw.department), status: s(raw.status) };
  if (!['scheduled', 'edit_hospital'].includes(a.status)) continue;
  const dt = DateTime.fromISO(a.date, { zone: TZ });
  if (!dt.isValid) continue;
  const offset = Math.round(dt.startOf('day').diff(today, 'days').days);
  if (!offsets.includes(offset)) continue;

  const p = patients.find((r) => s(r.patient_id) === a.patient_id);
  const patientUser = p ? userById(p.user_id) : null;
  const patientName = patientUser ? s(patientUser.name) : '';
  const recipients = [];
  if (patientUser) recipients.push({ user: patientUser, isFamily: false });
  for (const l of links) {
    if (s(l.patient_id) !== a.patient_id || s(l.status) !== 'active') continue;
    const fu = userById(l.family_user_id);
    if (fu) recipients.push({ user: fu, isFamily: true });
  }
  const seen = new Set();
  for (const r of recipients) {
    const uid = s(r.user.user_id), to = s(r.user.line_user_id);
    if (!to || seen.has(uid)) continue;
    seen.add(uid);
    if (alreadySent(a.appt_id, uid, offset)) continue;
    out.push({ json: {
      to, retryKey: uuid(),
      messages: reminder(a, offset, patientName, r.isFamily),
      log: { appt_id: a.appt_id, user_id: uid, channel: 'line', offset_days: offset },
    } });
  }
}
return out;

// 寫入 appointments 失敗（重試 3 次後）才會跑到這裡。
// Sheets 是整批寫入，失敗即視為這次所有寫入都沒成功。
const writes = $('決定動作').all().map(i => i.json).filter(j => j.kind === 'write');
const err = $input.first().json.error;
const errMsg = typeof err === 'string' ? err : (err && (err.message || JSON.stringify(err))) || '未知錯誤';
const tokens = [...new Set(writes.map(w => w.replyToken).filter(Boolean))];
return tokens.map(t => ({ json: {
  replyToken: t,
  messages: [{ type: 'text', text: '⚠️ 回診資料儲存失敗，這次的變更沒有生效。\n請稍後再試一次；若一直失敗請聯絡管理員。' }],
  apptIds: writes.filter(w => w.replyToken === t).map(w => w.row && w.row.appt_id).filter(Boolean).join(', '),
  errMsg: String(errMsg).slice(0, 300),
} }));

// 存檔失敗的事件已改回覆「儲存失敗」，replyToken 只能用一次，所以這裡把它們的成功訊息拿掉。
const f = $('存檔失敗｜整理回覆');
const failed = new Set(f.isExecuted ? f.all().map(i => i.json.replyToken) : []);
return $input.all().filter(i => !failed.has(i.json.replyToken));
